      tickets: 'سجّل هنا كل اتصال أو رسالة واتساب أو زيارة عن انقطاع أو عطل أو عداد أو فاتورة. كل طلب يأخذ رقماً. حدّد المسؤول، أضف ملاحظات، وأغلقه عند الانتهاء. الطلبات العاجلة والمتأخرة تظهر في الأعلى.',
      maintenance: 'أضف لكل مولد أعمال الصيانة: مثلاً تغيير الزيت كل 250 ساعة تشغيل، وفلتر الهواء كل 90 يوماً. أدخل عداد الساعات في سجل المولد؛ يصبح السطر برتقالياً عند الاقتراب وأحمر عند الاستحقاق. اضغط «تم العمل» بعد الصيانة.',
