    saved: 'تم الحفظ', openRates: 'افتح أسعار الصرف ←', makeLogin: 'إنشاء دخول للموظف', makeLoginHint: 'يستعمل البريد أعلاه ودور «موظف» الجاهز: بصمة الدخول والخروج، الإجازات، وقسائم راتبه فقط',
    loginMade: 'تم إنشاء دخول لـ {{email}}. كلمة السر المؤقتة (تظهر مرة واحدة): {{password}} — يستطيع الموظف تغييرها بعد الدخول.', title: 'الموظفون والرواتب', add: 'إضافة', save: 'حفظ', cancel: 'إلغاء', approve: 'موافقة', reject: 'رفض', print: 'طباعة', apply: 'تطبيق',
