    m: { people: 'الموظفون', attendance: 'الدوام والحضور', leave: 'الإجازات', payroll: 'الرواتب', rules: 'قواعد الرواتب', reports: 'تقارير الموظفين', self: 'صفحتي' },
    help: {
      people: { title: 'الموظفون', body: 'ملف واحد لكل موظف: البيانات الشخصية، العقد، الراتب، المستندات، الإجازات والحضور.\n\nيمكن تقسيم الراتب على عملتين (مثلاً 600 دولار + 10,000,000 ل.ل). الضمان وضريبة الرواتب تُحسب بالعملة الرسمية للبلد وتُقتطع من الجزء المدفوع بتلك العملة.\n\nاربط مستخدماً بالموظف ليسجّل حضوره ويطلب إجازة ويرى قسائم راتبه من هاتفه.' },
      attendance: { title: 'الدوام والحضور', body: 'كشف اليوم يُظهر كل الموظفين: حاضر، غائب، في إجازة أو عطلة. صحّح الوقت واضغط حفظ.\n\nآلات البصمة: صدّر السجل بصيغة CSV (رقم المستخدم + الوقت) واستورده هنا. أول بصمة في اليوم هي الوصول وآخر بصمة هي المغادرة. يُطابق الموظف برقمه على الآلة وإلا برمزه.\n\nالتأخير يُحسب بعد دقائق السماح في الدوام، والساعات الإضافية هي ما زاد عن الدوام.' },
      leave: { title: 'الإجازات', body: 'يطلب الموظف الإجازة من هاتفه، ويوافق مديره أو المسؤول عن الرواتب أو يرفض.\n\nالإجازة السنوية تتجمّع شهراً بشهر (أو مرة في السنة) من تاريخ التوظيف، ويجب أن يتّسع الرصيد للطلب. الإجازة غير المدفوعة تُحسم من الراتب.' },
      payroll: { title: 'الرواتب', body: 'تُحضّر الرواتب لكل موظف فعّال من ملفه، الحضور، الإجازات الموافق عليها، العمولات، السلف وقواعد البلد.\n\nمسودة ← موافق عليها (مقفلة) ← مرحّلة (قيد محاسبي) ← مدفوعة (من صندوق، مرة لكل عملة).\n\nكل قسيمة تُظهر كل سطر وطريقة حسابه. حصة صاحب العمل تظهر بين قوسين: هي كلفة على الشركة ولا تُحسم من الموظف.' },
      rules: { title: 'قواعد الرواتب', body: 'كل نسبة وسقف وتعويض تستعمله الرواتب، كما هو نافذ في التاريخ المختار. القيم الافتراضية للبلد تأتي مع Paxve؛ غيّر أي قيمة ابتداءً من تاريخ عندما يتغيّر القانون، فتبقى الرواتب القديمة على القيمة القديمة.\n\nشطور الضريبة تُكتب حد:نسبة، مثلاً 360000000:2,900000000:4,:25 (الأخير بلا حد).' },
      reports: { title: 'تقارير الموظفين', body: 'سجل الرواتب (كل سطر من كل قسيمة)، تصريح الضمان، ضريبة الرواتب، كلفة كل موظف / قسم / مركز كلفة، الحضور والإجازات. انقر بالزر الأيمن على الجدول لتصديره إلى Excel أو طباعته.' },
    },
