      dash: { title: 'نظرة عامة على المنصة', body: 'كل مؤسسة سجّلت في Paxve، مصنّفة حسب وضعها: في التجربة، نشطة (مدفوعة)، في فترة السماح (انتهى التاريخ لكنها تستطيع العمل بضعة أيام)، منتهية (تستطيع المشاهدة والتصدير دون حفظ)، وموقوفة (لا أحد يستطيع الدخول).\n\nالإيراد الشهري يجمع السعر الشهري لكل مؤسسة نشطة أو في فترة السماح؛ الباقة السنوية تُحسب بجزء من اثني عشر. اضغط على أي مربع لفتح القائمة.' },
      orgs: { title: 'المؤسسات', body: 'صفِّ حسب الوضع أو الباقة أو البلد، أو ابحث. اضغط بالزر الأيمن على الجدول للتصدير إلى Excel / CSV.\n\nاختر مؤسسة لترى مستخدميها وشركاتها واستخدامها ودفعاتها وسجل كل عملية. «تجديد» يسجّل دفعة ويمدّد تاريخ «مدفوع حتى». «إيقاف» يمنع كل دخول ويُظهر سببك. «وضع الدعم» يفتح المؤسسة كمديرها للمشاهدة فقط مع شريط بنفسجي؛ أنهِه من الشريط.' },
      requests: { title: 'طلبات التجديد', body: 'المؤسسات تطلب التجديد أو تغيير الباقة من الإعدادات ← اشتراكي في Paxve، غالباً مع رقم تحويل Whish / OMT. تأكد من وصول المال ثم جدّد من الطلب: تُسجَّل الدفعة ويُغلق الطلب.' },
      payments: { title: 'الدفعات المستلمة', body: 'كل دفعة سُجّلت عند التجديد مع الفترة التي تغطيها. المجاميع لكل عملة تظهر في الأعلى.' },
      plans: { title: 'الباقات والأسعار', body: 'السعر الشهري والسنوي وحدود كل باقة (الاشتراكات النشطة، المستخدمون، الشركات؛ فارغ = بلا حد). تغيير الحد يطبَّق على المؤسسات الجديدة وعند التجديد؛ حدّد «طبّق هذه الحدود أيضاً» لتحديث المؤسسات الموجودة على الباقة.' },
